#!/data/service/hnp/bin/bash
# test_package/test.sh — functional tests for the avimetaedit executable
#
# Tests avimetaedit against MediaArea official AVI regression samples.
# GitCode PR diff cannot carry binary blobs, so the two small official
# samples (AAC / AC-3 audio) are embedded as base64 below and restored at
# runtime; the larger H.264/AVC sample is fetched upstream when the network
# is available.  All assertions run against restored samples.
set -eu

FAILURES=0
ASSERT=0

# ---- embedded official samples (base64, MediaArea-RegressionTestingFiles) ----
AAC_B64=""
AC3_B64=""

assert_grep() {
    ASSERT=$((ASSERT + 1))
    if grep -qE "$2" "$3"; then
        echo "  ✅ $1"
    else
        echo "  ❌ $1 (pattern '$2' not found in $3)"
        FAILURES=$((FAILURES + 1))
    fi
}

assert_eq() {
    ASSERT=$((ASSERT + 1))
    if [ "$2" = "$3" ]; then
        echo "  ✅ $1"
    else
        echo "  ❌ $1 (expected '$3', got '$2')"
        FAILURES=$((FAILURES + 1))
    fi
}

TESTDIR="$(mktemp -d "${TMPDIR:-/data/local/tmp}/avimetaedit-test.XXXXXX")"
trap 'rm -rf "$TESTDIR"' EXIT
cd "$TESTDIR"

echo "[setup] restoring embedded official AVI samples..."
echo "$AAC_B64" | base64 -d > AAC_file1.avi
echo "$AC3_B64" | base64 -d > AC-3_file1.avi
if command -v curl >/dev/null 2>&1; then
    curl -fsSL --max-time 60 \
      "https://raw.githubusercontent.com/MediaArea/MediaArea-RegressionTestingFiles/master/AVI/AVC/file1.avi" \
      -o AVC_file1.avi 2>/dev/null && echo "  [info] AVC sample downloaded" || \
      echo "  [info] AVC sample unavailable (offline)"
else
    echo "  [info] curl not available, using embedded samples only"
fi
echo ""

echo "[1] --Version"
avimetaedit --Version > version.txt 2>&1 || true
if grep -qE "AVI MetaEdit 1\.0\.2" version.txt; then
    echo "  ✅ --Version prints AVI MetaEdit 1.0.2"
    ASSERT=$((ASSERT + 1))
else
    echo "  ❌ --Version prints AVI MetaEdit 1.0.2 (pattern not found)"
    echo "  ---- diagnostics ----"
    echo "  which avimetaedit: $(command -v avimetaedit 2>/dev/null || echo NOT_FOUND)"
    echo "  version.txt content:"
    sed 's/^/    /' version.txt 2>/dev/null | head -10
    echo "  -------------------"
    FAILURES=$((FAILURES + 1))
fi

echo "[2] Parse official AVI samples (AAC / AC-3, [AVC when available])"
avimetaedit --out-tech AC-3_file1.avi > ac3.csv 2>&1
assert_grep "AC-3 sample: AC-3 audio stream" "AC-3,2000,1,48000" ac3.csv
assert_grep "AC-3 sample: INFO chunk present" ",Yes," ac3.csv
avimetaedit --out-tech AAC_file1.avi > aac.csv 2>&1
assert_grep "AAC sample: AAC audio stream" "AAC,00FF,1,48000" aac.csv
if [ -s AVC_file1.avi ]; then
    avimetaedit --out-tech AVC_file1.avi > avc.csv 2>&1
    assert_grep "AVC sample: AVI + H.264" "AVC,H264,25\.000,720,576" avc.csv
else
    echo "  ⚠️ AVC sample skipped (not available offline)"
fi

echo "[3] XMP insert + export round-trip"
cp AC-3_file1.avi x.avi
cat > x.avi.XMP.xml <<'EOF'
<XMP xmlns="adobe:ns:meta/" xmlns:xmp="http://ns.adobe.com/xap/1.0/">
<xmp:MetadataDate>2026-08-22</xmp:MetadataDate>
</XMP>
EOF
avimetaedit --in-XMP-xml x.avi >/dev/null 2>&1
avimetaedit --out-tech x.avi > x.csv 2>&1
xmp_col=$(sed -n '2p' x.csv | cut -d, -f21)
assert_eq "XMP chunk written after --in-XMP-xml" "$xmp_col" "Yes"
rm -f x.avi.XMP.xml
avimetaedit --out-XMP-xml x.avi >/dev/null 2>&1
assert_grep "XMP export produces file & content" "MetadataDate" x.avi.XMP.xml

echo "[4] aXML insert"
cp AC-3_file1.avi a.avi
cat > a.avi.aXML.xml <<'EOF'
<aXML xmlns="http://www.gd-wai.org/">
<item>avimetaedit-test</item>
</aXML>
EOF
avimetaedit --in-aXML-xml a.avi >/dev/null 2>&1
avimetaedit --out-tech a.avi > a.csv 2>&1
axml_col=$(sed -n '2p' a.csv | cut -d, -f22)
assert_eq "aXML chunk written" "$axml_col" "Yes"

echo "[5] INFO chunk editing (--ISFT)"
cp AC-3_file1.avi i.avi
avimetaedit --ISFT=ohos-conan i.avi >/dev/null 2>&1
avimetaedit --out-tech i.avi > i.csv 2>&1
info_col=$(sed -n '2p' i.csv | cut -d, -f20)
assert_eq "INFO chunk present after --ISFT" "$info_col" "Yes"

echo "[6] MD5 generate + embed"
cp AC-3_file1.avi m.avi
avimetaedit --MD5-Generate --MD5-Embed m.avi >/dev/null 2>&1
avimetaedit --out-tech m.avi > m.csv 2>&1
md5_stored=$(sed -n '2p' m.csv | cut -d, -f24)
assert_eq "MD5 embedded (32 hex chars)" "${#md5_stored}" "32"

echo "[7] --simulate does not modify the file"
cp AC-3_file1.avi s.avi
before=$(md5sum s.avi | cut -d' ' -f1)
cat > s.avi.XMP.xml <<'EOF'
<XMP xmlns="adobe:ns:meta/" xmlns:xmp="http://ns.adobe.com/xap/1.0/">
<xmp:MetadataDate>2026-08-22</xmp:MetadataDate>
</XMP>
EOF
avimetaedit --simulate --in-XMP-xml s.avi >/dev/null 2>&1
after=$(md5sum s.avi | cut -d' ' -f1)
assert_eq "--simulate leaves file untouched" "$after" "$before"

echo "[8] Keep media data intact after XMP insertion"
cp AC-3_file1.avi k.avi
avimetaedit --in-XMP-xml k.avi >/dev/null 2>&1
avimetaedit --out-tech k.avi > k.csv 2>&1
k_aud=$(sed -n '2p' k.csv | cut -d, -f12)
assert_eq "Audio stream preserved after edit" "$k_aud" "AC-3"

echo ""
echo "==== avimetaedit test_package summary ===="
echo "  assertions: $ASSERT, failures: $FAILURES"
if [ "$FAILURES" -ne 0 ]; then
    echo "❌ $FAILURES assertion(s) failed"
    exit 1
fi
echo "✅ all assertions passed"
